# Greedy vs A*: compare paths on the same weighted graph
# Each edge is (neighbor, cost). h = heuristic (estimated distance to G)

graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('D', 2), ('E', 5)],
    'C': [('F', 1)],
    'D': [],
    'E': [('G', 1)],
    'F': [('G', 3)],
    'G': []
}
h = {'A': 6, 'B': 4, 'C': 4, 'D': 2, 'E': 1, 'F': 3, 'G': 0}

def greedy(start, goal):
    frontier = [(h[start], start, [start], 0)]
    visited = set()
    while frontier:
        frontier.sort()
        _, node, path, cost = frontier.pop(0)
        if node == goal:
            return path, cost
        if node in visited:
            continue
        visited.add(node)
        for nb, edge_cost in graph[node]:
            if nb not in visited:
                frontier.append((h[nb], nb, path + [nb], cost + edge_cost))
    return None, 0

def astar(start, goal):
    frontier = [(h[start], 0, start, [start])]
    visited = set()
    while frontier:
        frontier.sort()
        f, g, node, path = frontier.pop(0)
        if node == goal:
            return path, g
        if node in visited:
            continue
        visited.add(node)
        for nb, edge_cost in graph[node]:
            if nb not in visited:
                new_g = g + edge_cost
                frontier.append((new_g + h[nb], new_g, nb, path + [nb]))
    return None, 0

g_path, g_cost = greedy('A', 'G')
a_path, a_cost = astar('A', 'G')

print(f"Greedy path : {' → '.join(g_path)} | cost = {g_cost}")
print(f"A* path     : {' → '.join(a_path)} | cost = {a_cost}")
print()
print("A* is optimal — it balances actual cost + heuristic estimate.")
print("Greedy is faster but can miss the true shortest path.")

